import type {
  MutationGrantDefinition,
  MutationAcquisitionOption,
  MutationAcquisitionState,
  MutationAcquisitionStep,
  MutationModifier,
} from "../../../../types/mutants-handbook";
import type { AcquisitionServices } from "./types";
import { addGrant, addModifier, indexedValue } from "./values";

interface MaterializeContext {
  announcements: (() => Promise<void>)[];
  mutationName: string;
  services: AcquisitionServices;
  state: MutationAcquisitionState;
  topLevelRolls: Record<string, number>;
}

function concreteModifier(
  modifier: MutationModifier,
  key: string,
  value: number | undefined,
): MutationModifier {
  const { roll: _roll, ...copy } = modifier as MutationModifier & { roll?: string };
  return {
    ...copy,
    key,
    ...(value === undefined ? {} : { value }),
  } as MutationModifier;
}

function concreteGrant(
  grant: MutationGrantDefinition,
  state: MutationAcquisitionState,
  executionIndex: number,
): MutationGrantDefinition {
  const interpolate = (template: string) =>
    template.replaceAll(/{{([^{}]+)}}/g, (_match, key: string) => {
      const selected = indexedValue(state.selections, key.trim(), executionIndex);
      if (selected === undefined) {
        throw new Error(`Acquisition grant ${grant.key} has an unresolved {{${key}}} placeholder.`);
      }
      return selected;
    });
  const nameTemplate = grant.configure?.nameTemplate;
  const aggregateKeyTemplate = grant.aggregateKeyTemplate;
  if (!nameTemplate && !aggregateKeyTemplate) return grant;
  const { aggregateKeyTemplate: _aggregateTemplate, ...copy } = grant;
  const { nameTemplate: _nameTemplate, ...configuration } = grant.configure ?? {};
  return {
    ...copy,
    ...(aggregateKeyTemplate ? { aggregateKey: interpolate(aggregateKeyTemplate) } : {}),
    ...(grant.configure
      ? {
          configure: {
            ...configuration,
            ...(nameTemplate ? { name: interpolate(nameTemplate) } : {}),
          },
        }
      : {}),
  };
}

export async function materializeOption(
  context: MaterializeContext,
  step: MutationAcquisitionStep,
  executionIndex: number,
  option: MutationAcquisitionOption,
): Promise<void> {
  for (const grant of option.grants ?? []) {
    addGrant(context.state.grants, concreteGrant(grant, context.state, executionIndex));
  }

  for (const modifier of option.modifiers ?? []) {
    const key = `${step.key}:${context.state.occurrence}:${executionIndex + 1}:${modifier.key}`;
    const formula = "roll" in modifier ? modifier.roll : undefined;
    let total = context.state.rolls[key];
    if (Array.isArray(total)) total = total[0];
    if (formula && (typeof total !== "number" || !Number.isFinite(total))) {
      const rolled = await context.services.roll(
        formula,
        `${context.mutationName}: ${step.prompt}`,
      );
      total = rolled.total;
      context.state.rolls[key] = total;
      if (rolled.announce) context.announcements.push(rolled.announce);
    }
    if (formula && (typeof total !== "number" || !Number.isFinite(total))) {
      throw new Error(`The acquisition modifier ${modifier.key} did not resolve a roll.`);
    }
    const concrete = concreteModifier(modifier, key, formula ? total : undefined);
    addModifier(context.state.modifiers, concrete);
    if (formula && typeof total === "number") context.topLevelRolls[key] = total;
  }
}
