import { AcquisitionEngine } from "./engine";
import { mergeAcceptedBlocks } from "./state";
import type {
  AcquisitionResolution,
  AcquisitionServices,
  ResolveAcquisitionRequest,
} from "./types";
import { acquisitionModifierRolls, cloneState } from "./values";

export async function resolveMutationAcquisition(
  request: ResolveAcquisitionRequest,
  services: AcquisitionServices,
): Promise<AcquisitionResolution> {
  const initial = request.initialState;
  const retainedComplete = (request.retainedRolls ?? []).every((retained) =>
    Number.isFinite(initial?.rolls[retained.key]),
  );
  if (initial?.status !== "resolved" || !retainedComplete) {
    return new AcquisitionEngine(request, services).run();
  }

  const state = cloneState(initial, request.occurrence);
  state.grants = [...initial.grants];
  state.modifiers = [...initial.modifiers];
  state.acceptedBlocks = mergeAcceptedBlocks(initial.acceptedBlocks, request.acceptedBlocks);
  state.status = "resolved";
  return {
    announcements: [],
    retainedRolls: {
      ...acquisitionModifierRolls(state),
      ...Object.fromEntries(
        (request.retainedRolls ?? []).map((retained) => [retained.key, state.rolls[retained.key]]),
      ),
    } as Record<string, number>,
    state,
    status: "resolved",
  };
}
