import type { MutationAcquisitionState } from "../../../../types/mutants-handbook";
import type { AcquisitionChoiceRequest, AcquisitionServices } from "./types";

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

async function choose(request: AcquisitionChoiceRequest): Promise<string | undefined> {
  const descriptions = request.options.filter((option) => option.description);
  const notes = [
    ...(descriptions.length
      ? [
          '<ul class="tw:flex tw:flex-col tw:gap-2">',
          ...descriptions.map(
            (option) =>
              `<li><strong>${escapeHtml(option.label)}</strong><div class="tw:text-sm tw:opacity-70">${escapeHtml(option.description ?? "")}</div></li>`,
          ),
          "</ul>",
        ]
      : []),
  ];
  if (request.options.length > 4) {
    const content = [
      '<div class="fvtt-wfrp-ratter-root tw:flex tw:flex-col tw:gap-2">',
      '<fieldset class="tw:dui-fieldset">',
      `<legend class="tw:dui-fieldset-legend">${escapeHtml(request.prompt)}</legend>`,
      '<select class="tw:dui-select tw:w-full" name="mutation-acquisition-choice">',
      ...request.options.map(
        (option) => `<option value="${escapeHtml(option.id)}">${escapeHtml(option.label)}</option>`,
      ),
      "</select>",
      "</fieldset>",
      ...notes,
      "</div>",
    ].join("");
    const result = await foundry.applications.api.DialogV2.wait({
      buttons: [
        {
          action: "save",
          callback: (_event, button) => {
            const element = button.form?.elements.namedItem("mutation-acquisition-choice");
            return element instanceof HTMLSelectElement ? element.value : undefined;
          },
          default: true,
          label: "Select",
        },
        { action: "cancel", callback: () => undefined, label: "Cancel" },
      ],
      content,
      rejectClose: false,
      window: { title: request.title },
    });
    return typeof result === "string" && request.options.some((option) => option.id === result)
      ? result
      : undefined;
  }

  const content = [
    '<div class="fvtt-wfrp-ratter-root tw:flex tw:flex-col tw:gap-2">',
    `<p>${escapeHtml(request.prompt)}</p>`,
    ...notes,
    "</div>",
  ].join("");
  const result = await foundry.applications.api.DialogV2.wait({
    buttons: request.options.map((option, index) => ({
      action: option.id,
      callback: () => option.id,
      default: index === 0,
      label: option.label,
    })),
    content,
    rejectClose: false,
    window: { title: request.title },
  });
  return typeof result === "string" && request.options.some((option) => option.id === result)
    ? result
    : undefined;
}

async function input(prompt: string, title: string): Promise<string | undefined> {
  const result = await foundry.applications.api.DialogV2.wait({
    buttons: [
      {
        action: "save",
        callback: (_event, button) => {
          const element = button.form?.elements.namedItem("mutation-acquisition-value");
          return element instanceof HTMLInputElement ? element.value.trim() : undefined;
        },
        default: true,
        label: "Save",
      },
      { action: "cancel", callback: () => undefined, label: "Cancel" },
    ],
    content: `<fieldset class="fvtt-wfrp-ratter-root tw:dui-fieldset"><legend class="tw:dui-fieldset-legend">${escapeHtml(prompt)}</legend><input class="tw:dui-input tw:w-full" name="mutation-acquisition-value" type="text" autocomplete="off" required></fieldset>`,
    rejectClose: false,
    window: { title },
  });
  return typeof result === "string" && result.length > 0 ? result : undefined;
}

async function roll(formula: string, flavor: string) {
  const rolled = new Roll(formula);
  await rolled.evaluate({ allowInteractive: false });
  const total = rolled.total;
  if (typeof total !== "number" || !Number.isFinite(total)) {
    throw new Error(`Acquisition roll ${formula} did not produce a finite total.`);
  }
  return {
    announce: async () => {
      await rolled.toMessage({ flavor });
    },
    total,
  };
}

export const foundryAcquisitionServices: AcquisitionServices = {
  choose,
  input: ({ prompt, title }) => input(prompt, title),
  roll,
};

function summaryRows(values: Record<string, number | number[] | string | string[]>): string[] {
  return Object.entries(values).map(
    ([key, value]) =>
      `<div><dt class="tw:font-semibold">${escapeHtml(key)}</dt><dd>${escapeHtml(Array.isArray(value) ? value.join(", ") : String(value))}</dd></div>`,
  );
}

export async function reviewResolvedAcquisition(
  mutationName: string,
  state: MutationAcquisitionState,
): Promise<"keep" | "reconfigure"> {
  const warnings = (state.acceptedBlocks ?? []).map(
    (block) => `<li><span>${escapeHtml(block.message)}</span></li>`,
  );
  const content = [
    '<div class="fvtt-wfrp-ratter-root tw:flex tw:flex-col tw:gap-3">',
    "<p>This mutation already has a resolved acquisition. Keep it, or explicitly reconfigure its stored results.</p>",
    '<dl class="tw:grid tw:grid-cols-2 tw:gap-2">',
    ...summaryRows(state.selections),
    ...summaryRows(state.rolls),
    "</dl>",
    ...(warnings.length
      ? [
          '<div role="alert" class="tw:dui-alert tw:dui-alert-warning"><ul>',
          ...warnings,
          "</ul></div>",
        ]
      : []),
    "</div>",
  ].join("");
  const result = await foundry.applications.api.DialogV2.wait({
    buttons: [
      { action: "keep", callback: () => "keep", default: true, label: "Keep" },
      {
        action: "reconfigure",
        callback: () => "reconfigure",
        label: "Reconfigure",
      },
    ],
    content,
    rejectClose: false,
    window: { title: `Review ${mutationName}` },
  });
  return result === "reconfigure" ? "reconfigure" : "keep";
}
