import type {
  MutationAcquisitionState,
  MutationAcquisitionStep,
} from "../../../../types/mutants-handbook";
import { acceptedBlockMatches } from "./state";
import { AcquisitionBlocked, CANCELLED, createAcquisitionBlock } from "./signals";
import type { AcquisitionServices } from "./types";
import { indexedValue, setIndexedValue } from "./values";

interface TextResolutionRequest {
  executionIndex: number;
  mutationName: string;
  previousStates: readonly MutationAcquisitionState[];
  services: AcquisitionServices;
  state: MutationAcquisitionState;
  step: MutationAcquisitionStep;
}

export async function resolveAcquisitionText(request: TextResolutionRequest): Promise<void> {
  const { executionIndex, mutationName, previousStates, services, state, step } = request;
  const stored = indexedValue(state.selections, step.key, executionIndex);
  if (stored !== undefined) return;
  let value: string | undefined;
  if (state.occurrence > 1 && step.repeat === "copy-first") {
    const first = previousStates.find((entry) => entry.occurrence === 1);
    value = indexedValue(first?.selections ?? {}, step.key, executionIndex);
  }
  const used = new Set(
    previousStates.flatMap((entry) => {
      const selection = entry.selections[step.key];
      return Array.isArray(selection) ? selection : selection === undefined ? [] : [selection];
    }),
  );
  let rejected: string | undefined;
  for (let attempt = 0; value === undefined && attempt < 10; attempt += 1) {
    const entered = await services.input({ prompt: step.prompt, title: mutationName });
    if (entered === undefined) throw CANCELLED;
    rejected = entered;
    if (step.repeat !== "unique" || !used.has(entered)) value = entered;
  }
  if (value === undefined) {
    const block = createAcquisitionBlock(
      mutationName,
      step.prompt,
      "exhausted",
      "has no unique value remaining",
    );
    if (!acceptedBlockMatches(state.acceptedBlocks ?? [], block)) {
      throw new AcquisitionBlocked(block);
    }
    value = rejected;
  }
  if (value === undefined) throw new Error(`Acquisition step ${step.key} has no text fallback.`);
  setIndexedValue(state.selections, step.key, executionIndex, value);
}
