import {
  getChaosSpawnNatures,
  getCorruptionLoss,
  getReducedCorruption,
} from "../../../functions/mutants-handbook/rules";
import type {
  CharacteristicBonuses,
  ChosenPatron,
  MutationNature,
} from "../../../types/mutants-handbook";
import type { WfrpActor } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { chooseChaosPatron, spendResilience } from "./dialogs";
import { reconcileMutationAutomation } from "./automation/grant-reconciliation";
import {
  getMutationCounts,
  getMutationAcquisitionBlockDetails,
  hasPossessedMutation,
  retirePossessedMutations,
  retireSkinwalkerMutations,
  restoreRetiredMutations,
  type MutationAcquisitionBlock,
  type ResolvedMutation,
} from "./documents";
import {
  formatMutationMessage,
  postMutationMessage,
  reportMutationError,
  warnAboutMutation,
} from "./messages";
import { CHAOS_SPAWN_FLAG, CHOSEN_PATRON_FLAG } from "./constants";
import { updateActor } from "./updates";

const chosenPatronPath = `flags.${MODULE_ID}.${CHOSEN_PATRON_FLAG}`;
const chaosSpawnPath = `flags.${MODULE_ID}.${CHAOS_SPAWN_FLAG}`;

export interface ApplyMutationOptions {
  acceptedBlocks?: MutationAcquisitionBlock[];
  canReroll?: boolean;
}

export type ApplyMutationResult = "applied" | "cancelled" | "reroll";

function isAcceptedBlock(
  acceptedBlocks: readonly MutationAcquisitionBlock[] | undefined,
  block: MutationAcquisitionBlock,
): boolean {
  return (
    acceptedBlocks?.some(
      (accepted) => accepted.kind === block.kind && accepted.message === block.message,
    ) === true
  );
}

async function rollbackCreatedMutation(
  actor: WfrpActor,
  createdItemIds: readonly string[],
  retiredMutationIds: readonly string[],
  originalError: unknown,
): Promise<never> {
  const errors: unknown[] = [originalError];
  try {
    await restoreRetiredMutations(actor, retiredMutationIds);
  } catch (error) {
    errors.push(error);
  }
  try {
    await actor.deleteEmbeddedDocuments("Item", [...createdItemIds]);
  } catch (error) {
    errors.push(error);
  }
  if (errors.length > 1) {
    throw new AggregateError(errors, `Failed to roll back mutation acquisition for ${actor.name}.`);
  }
  throw originalError;
}

function getBonuses(actor: WfrpActor): CharacteristicBonuses {
  return {
    toughness: Number(actor.system.characteristics.t.bonus),
    willpower: Number(actor.system.characteristics.wp.bonus),
  };
}

function getActorCorruptionLoss(actor: WfrpActor, nature: MutationNature): number {
  return getCorruptionLoss(nature, getBonuses(actor));
}

function displayName(value: string): string {
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

async function shouldSpendResilience(actor: WfrpActor, outcomeName: string): Promise<boolean> {
  const resilience = Number(actor.system.status.resilience.value);
  return resilience > 0 && (await spendResilience(actor.name, outcomeName));
}

async function updateAfterMutationRoll(
  actor: WfrpActor,
  loss: number,
  spend: boolean,
  additionalChanges: Record<string, unknown> = {},
): Promise<void> {
  const changes: Record<string, unknown> = {
    ...additionalChanges,
    "system.status.corruption.value": getReducedCorruption(
      Number(actor.system.status.corruption.value),
      loss,
    ),
  };

  if (spend) {
    changes["system.status.resilience.value"] = Math.max(
      0,
      Number(actor.system.status.resilience.value) - 1,
    );
  }

  await updateActor(actor, changes);
}

async function announceChaosSpawn(
  actor: WfrpActor,
  exceededNatures: MutationNature[],
): Promise<void> {
  for (const nature of exceededNatures) {
    const message = formatMutationMessage("ChaosSpawn", {
      bonus: nature === "physical" ? "Toughness Bonus" : "Willpower Bonus",
      name: actor.name,
      nature,
    });
    warnAboutMutation(message);
    await postMutationMessage(message);
  }
}

export async function applyMutation(
  actor: WfrpActor,
  mutation: ResolvedMutation,
  options: ApplyMutationOptions = {},
): Promise<ApplyMutationResult> {
  const unacceptedBlock = getMutationAcquisitionBlockDetails(actor, mutation).find(
    (block) => !isAcceptedBlock(options.acceptedBlocks, block),
  );
  if (unacceptedBlock) {
    throw new Error(unacceptedBlock.message);
  }
  const spend = await shouldSpendResilience(actor, mutation.name);

  if (spend) {
    const loss = getActorCorruptionLoss(actor, mutation.nature);
    await updateAfterMutationRoll(actor, loss, true);
    await postMutationMessage(
      formatMutationMessage("Resisted", {
        loss,
        mutation: mutation.name,
        name: actor.name,
      }),
    );
    return "applied";
  }

  const loss = getActorCorruptionLoss(actor, mutation.nature);
  const creationOptions: Record<string, unknown> = {
    mutationAcquisitionAcceptedBlocks: options.acceptedBlocks ?? [],
    mutationAcquisitionCanReroll: options.canReroll === true,
    mutationAcquisitionHandlesChimeranRetirement: true,
  };
  const createdItems = await actor.createEmbeddedDocuments(
    "Item",
    [mutation.data],
    creationOptions,
  );

  if (createdItems.length === 0 && creationOptions["mutationAcquisitionCancelled"] === true) {
    if (creationOptions["mutationAcquisitionRerollRequested"] === true) return "reroll";
    warnAboutMutation(`${mutation.name} acquisition was cancelled. Corruption was not changed.`);
    return "cancelled";
  }

  if (createdItems.length !== 1) {
    if (createdItems.length > 0) {
      await actor.deleteEmbeddedDocuments(
        "Item",
        createdItems.map((item) => item.id),
      );
    }

    throw new Error(`Foundry did not create the ${mutation.name} mutation Item.`);
  }

  let exceededNatures: MutationNature[];
  let retiredSkinwalkerIds: string[] = [];

  try {
    if (mutation.name.trim().toLowerCase() === "chimeran curse") {
      retiredSkinwalkerIds = await retireSkinwalkerMutations(actor);
    }
    exceededNatures = getChaosSpawnNatures(getMutationCounts(actor), getBonuses(actor));
    const additionalChanges = exceededNatures.length > 0 ? { [chaosSpawnPath]: true } : {};
    await updateAfterMutationRoll(actor, loss, false, additionalChanges);
  } catch (error) {
    return rollbackCreatedMutation(
      actor,
      createdItems.map((item) => item.id),
      retiredSkinwalkerIds,
      error,
    );
  }

  if (retiredSkinwalkerIds.length > 0) {
    try {
      await reconcileMutationAutomation(actor.uuid);
    } catch (error) {
      reportMutationError(error);
    }
  }

  await postMutationMessage(
    formatMutationMessage("Gained", {
      loss,
      mutation: mutation.name,
      name: actor.name,
    }),
  );
  await announceChaosSpawn(actor, exceededNatures);
  return "applied";
}

export async function applyChosen(actor: WfrpActor, nature: MutationNature): Promise<void> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while applying Chosen of Chaos.");
  }

  const outcomeName = game.i18n.localize("FVTT_WFRP_RATTER.Mutations.ChosenOutcome");
  const spend = await shouldSpendResilience(actor, outcomeName);

  if (spend) {
    const loss = getActorCorruptionLoss(actor, nature);
    await updateAfterMutationRoll(actor, loss, true);
    await postMutationMessage(
      formatMutationMessage("Resisted", {
        loss,
        mutation: outcomeName,
        name: actor.name,
      }),
    );
    return;
  }

  const patron = await chooseChaosPatron(actor.name);
  const chosenPatron: ChosenPatron = patron ?? "unassigned";
  const hadPossessedMutation = hasPossessedMutation(actor);
  const loss = getActorCorruptionLoss(actor, nature);
  await updateAfterMutationRoll(actor, loss, false, {
    [chosenPatronPath]: chosenPatron,
  });
  if (hadPossessedMutation) {
    await retirePossessedMutations(actor);
    await reconcileMutationAutomation(actor.uuid);
  }

  const messageKey = patron ? "Chosen" : "ChosenUnassigned";
  await postMutationMessage(
    formatMutationMessage(messageKey, {
      loss,
      name: actor.name,
      patron: patron ? displayName(patron) : "Chaos",
    }),
  );

  if (hadPossessedMutation) {
    const possessedMessage = formatMutationMessage("PossessedRemoved", { name: actor.name });
    warnAboutMutation(possessedMessage);
    await postMutationMessage(possessedMessage);
  }
}
