import type {
  MutationAcquisitionOption,
  MutationAcquisitionState,
  MutationAcquisitionStep,
} from "../../../../types/mutants-handbook";
import { materializeOption } from "./materialize";
import { acceptOrBlockOption, advanceOption, conditionalAdvanceOption } from "./progression";
import { repeatEligibilityDetail } from "./repeat";
import { AcquisitionBlocked, CANCELLED, createAcquisitionBlock, LIMITS } from "./signals";
import { acceptedBlockMatches, mergeAcceptedBlocks } from "./state";
import { resolveAcquisitionText } from "./text";
import type {
  AcquisitionResolution,
  AcquisitionRollResult,
  AcquisitionServices,
  ResolveAcquisitionRequest,
} from "./types";
import {
  cloneState,
  conditionsMatch,
  indexedValue,
  setIndexedValue,
  unusedOptions,
} from "./values";

export class AcquisitionEngine {
  readonly announcements: (() => Promise<void>)[] = [];
  readonly executionCounts = new Map<string, number>();
  readonly facts: Readonly<Record<string, unknown>>;
  readonly previous: readonly MutationAcquisitionState[];
  readonly state: MutationAcquisitionState;
  readonly stepsByKey: Map<string, MutationAcquisitionStep>;
  readonly topLevelRolls: Record<string, number> = {};
  resolutions = 0;

  get mutationName(): string {
    return this.request.mutationName;
  }

  constructor(
    readonly request: ResolveAcquisitionRequest,
    readonly services: AcquisitionServices,
  ) {
    this.previous = request.previousStates ?? [];
    this.facts = request.facts ?? {};
    this.state = cloneState(request.initialState, request.occurrence);
    this.state.acceptedBlocks = mergeAcceptedBlocks(
      this.state.acceptedBlocks,
      request.acceptedBlocks,
    );
    this.stepsByKey = new Map((request.steps ?? []).map((step) => [step.key, step]));
  }

  async run(): Promise<AcquisitionResolution> {
    try {
      await this.resolveRetainedRolls();
      const referenced = new Set(
        (this.request.steps ?? []).flatMap((step) =>
          (step.options ?? []).flatMap((option) => (option.next ? [option.next] : [])),
        ),
      );
      for (const step of this.request.steps ?? []) {
        if (!referenced.has(step.key)) await this.visit(step, 0);
      }
      this.state.status = "resolved";
      return {
        announcements: this.announcements,
        retainedRolls: this.topLevelRolls,
        state: this.state,
        status: "resolved",
      };
    } catch (error) {
      if (error === CANCELLED) return { status: "cancelled" };
      if (error instanceof AcquisitionBlocked) {
        return {
          announcements: this.announcements,
          block: error.block,
          state: this.state,
          status: "blocked",
        };
      }
      throw error;
    }
  }

  private async resolveRetainedRolls(): Promise<void> {
    for (const retained of this.request.retainedRolls ?? []) {
      let total = this.state.rolls[retained.key];
      if (Array.isArray(total)) total = total[0];
      if (typeof total !== "number" || !Number.isFinite(total)) {
        const result = await this.roll(
          retained.formula,
          `${this.request.mutationName}: retained roll`,
        );
        total = result.total;
        this.state.rolls[retained.key] = total;
        if (result.announce) this.announcements.push(result.announce);
      }
      this.topLevelRolls[retained.key] = total;
    }
  }

  private async visit(step: MutationAcquisitionStep, depth: number): Promise<void> {
    if (depth > LIMITS.depth) {
      throw new Error("Mutation acquisition nesting exceeds its safe limit.");
    }
    if (!conditionsMatch(step.when, this.state, this.facts)) return;
    const eligibility = repeatEligibilityDetail(step, this.request.occurrence, this.previous);
    if (eligibility) {
      const block = createAcquisitionBlock(
        this.request.mutationName,
        step.prompt,
        "eligibility",
        eligibility,
      );
      if (!acceptedBlockMatches(this.state.acceptedBlocks ?? [], block)) {
        throw new AcquisitionBlocked(block);
      }
    }
    const count = Math.max(1, Math.trunc(step.count ?? 1));
    for (let repeat = 0; repeat < count; repeat += 1) await this.resolveStep(step, depth);
  }

  private async resolveStep(step: MutationAcquisitionStep, depth: number): Promise<void> {
    this.resolutions += 1;
    if (this.resolutions > LIMITS.resolutions) {
      throw new Error("Mutation acquisition contains too many nested resolutions.");
    }
    const index = this.executionCounts.get(step.key) ?? 0;
    this.executionCounts.set(step.key, index + 1);
    if (step.kind === "text") {
      await resolveAcquisitionText({
        executionIndex: index,
        mutationName: this.request.mutationName,
        previousStates: this.previous,
        services: this.services,
        state: this.state,
        step,
      });
      return;
    }

    const options = (step.options ?? []).filter((option) =>
      conditionsMatch(option.when, this.state, this.facts),
    );
    if (options.length === 0) throw new Error(`Acquisition step ${step.key} has no options.`);
    const stored = indexedValue(this.state.selections, step.key, index);
    const option = stored
      ? options.find((candidate) => candidate.id === stored)
      : await this.resolveOption(step, index, options);
    if (!option) throw new Error(`Acquisition step ${step.key} retained an unknown option.`);
    setIndexedValue(this.state.selections, step.key, index, option.id);
    if (option.next) {
      const next = this.stepsByKey.get(option.next);
      if (!next) throw new Error(`Acquisition step ${step.key} references missing ${option.next}.`);
      await this.visit(next, depth + 1);
    }
    await materializeOption(this, step, index, option);
  }

  private async resolveOption(
    step: MutationAcquisitionStep,
    index: number,
    options: readonly MutationAcquisitionOption[],
  ): Promise<MutationAcquisitionOption> {
    const repeated = this.request.occurrence > 1;
    if (!repeated && step.initial) {
      const initial = options.find((option) => option.id === step.initial);
      if (!initial) throw new Error(`Acquisition step ${step.key} has no initial option.`);
      return initial;
    }
    if (repeated && step.repeat === "copy-first") {
      const first = this.previous.find((state) => state.occurrence === 1);
      const id = indexedValue(first?.selections ?? {}, step.key, index);
      const copied = options.find((option) => option.id === id);
      if (copied) return copied;
    }
    if (repeated && step.repeat === "advance") {
      return advanceOption(this.request, this.state, step, index, options);
    }
    if (repeated && step.repeat === "conditional-advance") {
      return conditionalAdvanceOption(this.request, this.state, step, index, options);
    }

    const eligible =
      repeated && step.repeat === "unique"
        ? unusedOptions(step.key, options, [...this.previous, this.state])
        : options;
    if (eligible.length === 0) {
      const latest = indexedValue(this.previous.at(-1)?.selections ?? {}, step.key, index);
      return acceptOrBlockOption(
        this.request,
        this.state,
        step,
        options.find((option) => option.id === latest) ?? options.at(-1),
        "exhausted",
        "has no further result remaining",
      );
    }
    if (step.kind === "choice" && (step.options?.length ?? 0) > 1 && eligible.length === 1) {
      return eligible[0] as MutationAcquisitionOption;
    }
    return step.kind === "table"
      ? this.resolveTable(step, index, eligible)
      : this.choose(step, eligible);
  }

  private async resolveTable(
    step: MutationAcquisitionStep,
    index: number,
    options: readonly MutationAcquisitionOption[],
  ): Promise<MutationAcquisitionOption> {
    const method = await this.choose(step, [
      { id: "roll", label: "Roll" },
      { id: "choose", label: "Choose" },
    ]);
    if (method.id === "choose") return this.choose(step, options);
    for (let attempt = 0; attempt < LIMITS.tableRolls; attempt += 1) {
      const result = await this.roll(
        step.formula ?? "1d100",
        `${this.request.mutationName}: ${step.prompt}`,
      );
      const matches = options.filter(
        (option) =>
          result.total >= (option.min ?? -Infinity) && result.total <= (option.max ?? Infinity),
      );
      if (matches.length === 0) continue;
      const selected = matches.length === 1 ? matches[0] : await this.choose(step, matches);
      setIndexedValue(this.state.rolls, step.key, index, result.total);
      if (result.announce) this.announcements.push(result.announce);
      return selected as MutationAcquisitionOption;
    }
    return acceptOrBlockOption(
      this.request,
      this.state,
      step,
      options.at(-1),
      "exhausted",
      "has no further result remaining",
    );
  }

  private async choose(
    step: MutationAcquisitionStep,
    options: readonly MutationAcquisitionOption[],
  ): Promise<MutationAcquisitionOption> {
    const selected = await this.services.choose({
      options,
      prompt: step.prompt,
      title: this.request.mutationName,
    });
    if (selected === undefined) throw CANCELLED;
    const option = options.find((candidate) => candidate.id === selected);
    if (!option) throw new Error(`Acquisition dialog returned unknown option ${selected}.`);
    return option;
  }

  private async roll(formula: string, flavor: string): Promise<AcquisitionRollResult> {
    const result = await this.services.roll(formula, flavor);
    if (!Number.isFinite(result.total))
      throw new Error(`Acquisition roll ${formula} was not finite.`);
    return result;
  }
}
