import { MODULE_ID } from "../../../constants";
import type { MutationActionActor, MutationActionItem, MutationActionTest } from "./types";

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function mutationActionActor(value: unknown): MutationActionActor | undefined {
  return isRecord(value) ? (value as MutationActionActor) : undefined;
}

export function mutationActionItem(value: unknown): MutationActionItem | undefined {
  return isRecord(value) ? (value as MutationActionItem) : undefined;
}

export function mutationActionTest(value: unknown): MutationActionTest | undefined {
  return isRecord(value) ? (value as MutationActionTest) : undefined;
}

export function actionContext(test: MutationActionTest): Record<string, unknown> {
  if (!isRecord(test.context)) test.context = {};
  return test.context;
}

export function actionIdFromItem(item: MutationActionItem): string | undefined {
  const action = item.flags?.[MODULE_ID]?.["mutationAction"];
  return isRecord(action) && typeof action["actionId"] === "string"
    ? action["actionId"]
    : undefined;
}

export function testMatchesAction(
  item: MutationActionItem,
  actionId: string,
  test: MutationActionTest,
): boolean {
  const contextId = test.context?.["mutationActionId"];
  const optionId = test.preData?.options?.["mutationActionId"];
  const directItem = test.item;
  return (
    contextId === actionId ||
    optionId === actionId ||
    directItem?.id === item.id ||
    (directItem?.uuid !== undefined && directItem.uuid === item.uuid)
  );
}

export function actorItems(actor: MutationActionActor): MutationActionItem[] {
  try {
    return actor.items ? [...actor.items] : [];
  } catch {
    return [];
  }
}

export function activeMutationLevels(actor: MutationActionActor, mutationId: string): number {
  const mutations = actor.itemTypes?.["mutation"] ?? actorItems(actor);
  return mutations.filter((item) => {
    if (item.type !== undefined && item.type !== "mutation") return false;
    const flags = item.flags?.[MODULE_ID];
    const definition = flags?.["mutationAutomation"];
    const id = isRecord(definition) ? definition["definitionId"] : item.id;
    return (
      id === mutationId &&
      flags?.["mutantsHandbookRetired"] !== true &&
      flags?.["mutantsHandbookPossessionRemoved"] !== true
    );
  }).length;
}

export function activeMutationItem(
  actor: MutationActionActor,
  mutationId: string,
): MutationActionItem | undefined {
  return activeMutationItems(actor, mutationId)[0];
}

export function activeMutationItems(
  actor: MutationActionActor,
  mutationId: string,
): MutationActionItem[] {
  const mutations = actor.itemTypes?.["mutation"] ?? actorItems(actor);
  return mutations.filter((item) => {
    if (item.type !== undefined && item.type !== "mutation") return false;
    const flags = item.flags?.[MODULE_ID];
    const definition = flags?.["mutationAutomation"];
    const id = isRecord(definition) ? definition["definitionId"] : item.id;
    return (
      id === mutationId &&
      flags?.["mutantsHandbookRetired"] !== true &&
      flags?.["mutantsHandbookPossessionRemoved"] !== true
    );
  });
}

export function mutationAcquisition(item: MutationActionItem | undefined): Record<string, unknown> {
  const direct = item?.flags?.[MODULE_ID]?.["mutationAutomation"];
  const flagged = item?.getFlag?.(MODULE_ID, "mutationAutomation");
  const automation = isRecord(direct) ? direct : isRecord(flagged) ? flagged : undefined;
  const state = isRecord(automation?.["state"]) ? automation["state"] : undefined;
  const acquisition = isRecord(state?.["acquisition"]) ? state["acquisition"] : undefined;
  return acquisition?.["status"] === "resolved" ? acquisition : {};
}
