import { registerModuleApi } from "../api/register-module-api";
import { registerModuleSettings } from "../settings";
import { registerHandbookTestContextOptions } from "../wfrp4e/mutants-handbook/context-options";
import { registerMutationAutomationHooks } from "../wfrp4e/mutants-handbook/automation/hooks";
import { migrateOwnedMutationAutomation } from "../wfrp4e/mutants-handbook/automation/migration";
import { reportMutationError } from "../wfrp4e/mutants-handbook/messages";
import { installMutantsHandbookReplacement } from "../wfrp4e/mutants-handbook/replacement";
import { registerMutationCompanionHooks } from "../wfrp4e/mutants-handbook/actions/companions";

export function registerModuleHooks(): void {
  Hooks.once("init", () => {
    registerModuleSettings();
    registerModuleApi();
    registerHandbookTestContextOptions();
    registerMutationAutomationHooks();
    registerMutationCompanionHooks();
  });

  Hooks.once("ready", async () => {
    installMutantsHandbookReplacement();
    try {
      await migrateOwnedMutationAutomation();
    } catch (error) {
      reportMutationError(error);
    }
  });
}
