import {
  resolveHandbookSpecies,
  resolveMutationNature,
  resolveMutationSeverity,
} from "../../../functions/mutants-handbook/rules";
import type { ChaosPatron, ChosenPatron } from "../../../types/mutants-handbook";
import type { WfrpActor } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { chooseChaosPatron, chooseHandbookSpecies, chooseMutationBlockAction } from "./dialogs";
import {
  getChosenPatron,
  getMutationAcquisitionBlockDetails,
  getMutationCounts,
  resolveMutationResult,
  type MutationAcquisitionBlock,
  type ResolvedMutation,
} from "./documents";
import { formatMutationMessage, postMutationMessage, warnAboutMutation } from "./messages";
import { applyChosen, applyMutation } from "./outcomes";
import { getPatronResultNote } from "./patron-notes";
import {
  drawMutation,
  drawMutationNature,
  drawMutationSeverity,
  drawPatronMutation,
} from "./tables";
import { CHOSEN_PATRON_FLAG } from "./constants";
import { updateActor } from "./updates";

const chosenPatronPath = `flags.${MODULE_ID}.${CHOSEN_PATRON_FLAG}`;
const MAX_REROLLS = 100;

type BlockReview =
  | { action: "accept"; acceptedBlocks: MutationAcquisitionBlock[] }
  | { action: "cancel" | "reroll"; block: MutationAcquisitionBlock };

function displayName(value: string): string {
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

async function reviewMutationBlocks(
  actor: WfrpActor,
  mutation: ResolvedMutation,
): Promise<BlockReview> {
  const acceptedBlocks: MutationAcquisitionBlock[] = [];
  for (const block of getMutationAcquisitionBlockDetails(actor, mutation)) {
    const action = await chooseMutationBlockAction(mutation.name, block, true);
    if (action !== "accept") return { action, block };
    acceptedBlocks.push(block);
  }
  return { action: "accept", acceptedBlocks };
}

async function resolveSelectedPatron(
  actor: WfrpActor,
  chosenPatron: ChosenPatron,
): Promise<ChaosPatron | undefined> {
  if (chosenPatron !== "unassigned") {
    return chosenPatron;
  }

  const patron = await chooseChaosPatron(actor.name);

  if (!patron) {
    warnAboutMutation(formatMutationMessage("PatronRequired", { name: actor.name }));
    return undefined;
  }

  await updateActor(actor, { [chosenPatronPath]: patron });
  return patron;
}

async function rollPatronMutation(actor: WfrpActor, chosenPatron: ChosenPatron): Promise<void> {
  const patron = await resolveSelectedPatron(actor, chosenPatron);

  if (!patron) {
    return;
  }

  let mutation: ResolvedMutation | undefined;
  for (let attempt = 0; attempt < MAX_REROLLS; attempt += 1) {
    const result = await drawPatronMutation(patron);
    const candidate = await resolveMutationResult(result, patron);
    const review = await reviewMutationBlocks(actor, candidate);
    if (review.action === "cancel") return;
    if (review.action === "reroll") {
      warnAboutMutation(
        `${review.block.message} Rerolling on the ${displayName(patron)} mutation table.`,
      );
      continue;
    }
    if (review.action !== "accept") continue;

    const outcome = await applyMutation(actor, candidate, {
      acceptedBlocks: review.acceptedBlocks,
      canReroll: true,
    });
    if (outcome === "reroll") continue;
    if (outcome === "cancelled") return;
    mutation = candidate;
    break;
  }
  if (!mutation) throw new Error("No eligible patron mutation could be drawn after 100 attempts.");
  const note = getPatronResultNote(patron, mutation.name);

  if (note) {
    await postMutationMessage(
      formatMutationMessage("PatronRestriction", {
        mutation: mutation.name,
        note,
        patron: displayName(patron),
      }),
    );
  }
}

async function rollStandardHandbookMutation(actor: WfrpActor): Promise<void> {
  const speciesValue = actor.system.details.species.value;
  const species =
    resolveHandbookSpecies(speciesValue) ?? (await chooseHandbookSpecies(actor.name, speciesValue));

  if (!species) {
    warnAboutMutation(formatMutationMessage("SpeciesRequired", { name: actor.name }));
    return;
  }

  const natureResult = await drawMutationNature(species);
  const nature = resolveMutationNature(natureResult.name);

  if (!nature) {
    throw new Error(`The nature table returned an unrecognized result: ${natureResult.name}.`);
  }

  const severityResult = await drawMutationSeverity(getMutationCounts(actor).total);
  const severity = resolveMutationSeverity(severityResult.name);

  if (!severity) {
    throw new Error(`The severity table returned an unrecognized result: ${severityResult.name}.`);
  }

  if (severity === "chosen") {
    await applyChosen(actor, nature);
    return;
  }

  let mutation: ResolvedMutation | undefined;
  for (let attempt = 0; attempt < MAX_REROLLS; attempt += 1) {
    const result = await drawMutation(nature, severity);

    if (!result.documentUuid && resolveMutationSeverity(result.name) === "chosen") {
      await applyChosen(actor, nature);
      return;
    }

    const candidate = await resolveMutationResult(result);
    const review = await reviewMutationBlocks(actor, candidate);
    if (review.action === "cancel") return;
    if (review.action === "reroll") {
      warnAboutMutation(
        `${review.block.message} Rerolling on the ${displayName(severity)} ${nature} table.`,
      );
      continue;
    }
    if (review.action !== "accept") continue;

    if (candidate.nature !== nature) {
      throw new Error(`${candidate.name} does not match the rolled ${nature} mutation table.`);
    }

    const outcome = await applyMutation(actor, candidate, {
      acceptedBlocks: review.acceptedBlocks,
      canReroll: true,
    });
    if (outcome === "reroll") continue;
    if (outcome === "cancelled") return;
    mutation = candidate;
    break;
  }
  if (!mutation) throw new Error("No eligible mutation could be drawn after 100 attempts.");
}

export async function runFailedCorruptionCheck(actor: WfrpActor): Promise<void> {
  const chosenPatron = getChosenPatron(actor);

  if (chosenPatron) {
    await rollPatronMutation(actor, chosenPatron);
  } else {
    await rollStandardHandbookMutation(actor);
  }
}
