import type {
  MutationAcquisitionBlockAudit,
  MutationAcquisitionOption,
  MutationAcquisitionState,
  MutationAcquisitionStep,
} from "../../../../types/mutants-handbook";
import { AcquisitionBlocked, createAcquisitionBlock } from "./signals";
import { acceptedBlockMatches } from "./state";
import type { ResolveAcquisitionRequest } from "./types";
import { conditionsMatch, indexedValue } from "./values";

export function acceptOrBlockOption(
  request: ResolveAcquisitionRequest,
  state: MutationAcquisitionState,
  step: MutationAcquisitionStep,
  fallback: MutationAcquisitionOption | undefined,
  kind: MutationAcquisitionBlockAudit["kind"],
  detail: string,
): MutationAcquisitionOption {
  if (!fallback) throw new Error(`Acquisition step ${step.key} has no fallback option.`);
  const block = createAcquisitionBlock(request.mutationName, step.prompt, kind, detail);
  if (acceptedBlockMatches(state.acceptedBlocks ?? [], block)) return fallback;
  throw new AcquisitionBlocked(block);
}

export function advanceOption(
  request: ResolveAcquisitionRequest,
  state: MutationAcquisitionState,
  step: MutationAcquisitionStep,
  index: number,
  options: readonly MutationAcquisitionOption[],
): MutationAcquisitionOption {
  const latest = request.previousStates?.at(-1);
  const isConsecutive = latest?.occurrence === request.occurrence - 1;
  const id = indexedValue(isConsecutive ? latest.selections : {}, step.key, index);
  const current = options.findIndex((option) => option.id === id);
  if (current < 0) {
    return acceptOrBlockOption(
      request,
      state,
      step,
      options[0],
      "eligibility",
      "cannot advance because no earlier resolved result is available",
    );
  }
  if (current >= options.length - 1) {
    return acceptOrBlockOption(
      request,
      state,
      step,
      options[current],
      "exhausted",
      "has no further result remaining",
    );
  }
  return options[current + 1] as MutationAcquisitionOption;
}

export function conditionalAdvanceOption(
  request: ResolveAcquisitionRequest,
  state: MutationAcquisitionState,
  step: MutationAcquisitionStep,
  index: number,
  options: readonly MutationAcquisitionOption[],
): MutationAcquisitionOption {
  const latest = request.previousStates?.at(-1);
  const id = indexedValue(latest?.selections ?? {}, step.key, index) ?? step.initial;
  const current = options.findIndex((option) => option.id === id);
  if (current < 0) {
    return acceptOrBlockOption(
      request,
      state,
      step,
      options[0],
      "eligibility",
      "cannot advance because no earlier resolved result is available",
    );
  }
  if (!conditionsMatch(step.advanceWhen, state, request.facts ?? {})) {
    return options[current] as MutationAcquisitionOption;
  }
  if (current >= options.length - 1) {
    return acceptOrBlockOption(
      request,
      state,
      step,
      options[current],
      "exhausted",
      "has no further result remaining",
    );
  }
  return options[current + 1] as MutationAcquisitionOption;
}
