import type {
  MutationAcquisitionCondition,
  MutationAcquisitionOption,
  MutationAcquisitionState,
  MutationGrantDefinition,
  MutationModifier,
} from "../../../../types/mutants-handbook";

type StoredValue = number | string;

export function indexedValue<T extends StoredValue>(
  values: Record<string, T | T[]>,
  key: string,
  index: number,
): T | undefined {
  const stored = values[key];
  return Array.isArray(stored) ? stored[index] : index === 0 ? stored : undefined;
}

export function unusedOptions(
  key: string,
  options: readonly MutationAcquisitionOption[],
  states: readonly MutationAcquisitionState[],
): readonly MutationAcquisitionOption[] {
  const used = new Set<string>();
  for (const state of states) {
    const value = state.selections[key];
    for (const id of Array.isArray(value) ? value : value === undefined ? [] : [value])
      used.add(id);
  }
  return options.filter((option) => !used.has(option.id));
}

export function setIndexedValue<T extends StoredValue>(
  values: Record<string, T | T[]>,
  key: string,
  index: number,
  value: T,
): void {
  const stored = values[key];
  const entries = Array.isArray(stored) ? [...stored] : stored === undefined ? [] : [stored];
  entries[index] = value;
  values[key] = entries.length === 1 ? (entries[0] as T) : entries;
}

function pathValue(root: unknown, path: readonly string[]): unknown {
  let current = root;
  for (const segment of path) {
    if (typeof current !== "object" || current === null) return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

function conditionValue(
  condition: MutationAcquisitionCondition,
  state: MutationAcquisitionState,
  facts: Readonly<Record<string, unknown>>,
): unknown {
  const context = {
    ...facts,
    acquisition: {
      occurrence: state.occurrence,
      rolls: state.rolls,
      selections: state.selections,
    },
    occurrence: state.occurrence,
    rolls: state.rolls,
    selections: state.selections,
  };
  const resolved = pathValue(context, condition.key.split("."));
  return resolved ?? state.selections[condition.key] ?? state.rolls[condition.key];
}

function same(left: unknown, right: unknown): boolean {
  return Array.isArray(left) || Array.isArray(right)
    ? JSON.stringify(left) === JSON.stringify(right)
    : left === right;
}

export function conditionsMatch(
  conditions: readonly MutationAcquisitionCondition[] | undefined,
  state: MutationAcquisitionState,
  facts: Readonly<Record<string, unknown>>,
): boolean {
  return (conditions ?? []).every((condition) => {
    const actual = conditionValue(condition, state, facts);
    const expected = condition.value;
    switch (condition.operator) {
      case "equals":
        return same(actual, expected);
      case "notEquals":
        return !same(actual, expected);
      case "exists":
        return actual !== undefined && actual !== null;
      case "notExists":
        return actual === undefined || actual === null;
      case "includes":
        return (
          (Array.isArray(actual) || typeof actual === "string") &&
          actual.includes(expected as never)
        );
      case "notIncludes":
        return !(
          (Array.isArray(actual) || typeof actual === "string") &&
          actual.includes(expected as never)
        );
      case "lt":
        return typeof actual === "number" && typeof expected === "number" && actual < expected;
      case "lte":
        return typeof actual === "number" && typeof expected === "number" && actual <= expected;
      case "gt":
        return typeof actual === "number" && typeof expected === "number" && actual > expected;
      case "gte":
        return typeof actual === "number" && typeof expected === "number" && actual >= expected;
      case "sumEquals": {
        const entries = Array.isArray(actual) ? actual : actual === undefined ? [] : [actual];
        const numbers = entries.map(Number);
        return (
          typeof expected === "number" &&
          numbers.length > 0 &&
          numbers.every(Number.isFinite) &&
          numbers.reduce((total, value) => total + value, 0) === expected
        );
      }
    }
  });
}

function withoutRanks(grant: MutationGrantDefinition): Record<string, unknown> {
  const { ranks: _ranks, ...rest } = grant;
  return rest;
}

export function addGrant(
  grants: MutationGrantDefinition[],
  incoming: MutationGrantDefinition,
): void {
  const index = grants.findIndex(
    (grant) => grant.key === incoming.key && grant.aggregateKey === incoming.aggregateKey,
  );
  if (index < 0) {
    grants.push({ ...incoming });
    return;
  }
  const existing = grants[index] as MutationGrantDefinition;
  if (incoming.aggregate === "latest") {
    grants[index] = { ...incoming };
    return;
  }
  if (JSON.stringify(withoutRanks(existing)) !== JSON.stringify(withoutRanks(incoming))) {
    throw new Error(`Acquisition grants reuse the incompatible key ${incoming.key}.`);
  }
  if (incoming.stack === "rank") {
    grants[index] = {
      ...existing,
      ranks: (existing.ranks ?? 1) + (incoming.ranks ?? 1),
    };
  }
}

export function addModifier(modifiers: MutationModifier[], incoming: MutationModifier): void {
  const index = modifiers.findIndex((modifier) => modifier.key === incoming.key);
  if (index < 0) {
    modifiers.push({ ...incoming });
    return;
  }
  if (JSON.stringify(modifiers[index]) !== JSON.stringify(incoming)) {
    throw new Error(`Acquisition modifiers reuse the incompatible key ${incoming.key}.`);
  }
}

export function cloneState(
  state: MutationAcquisitionState | undefined,
  occurrence: number,
): MutationAcquisitionState {
  return {
    acceptedBlocks: [...(state?.acceptedBlocks ?? [])],
    grants: [],
    modifiers: [],
    occurrence,
    rolls: Object.fromEntries(
      Object.entries(state?.rolls ?? {}).map(([key, value]) => [
        key,
        Array.isArray(value) ? [...value] : value,
      ]),
    ),
    selections: Object.fromEntries(
      Object.entries(state?.selections ?? {}).map(([key, value]) => [
        key,
        Array.isArray(value) ? [...value] : value,
      ]),
    ),
    status: "pending",
    version: 1,
  };
}

export function acquisitionModifierRolls(state: MutationAcquisitionState): Record<string, number> {
  const keys = new Set(state.modifiers.map((modifier) => modifier.key));
  return Object.fromEntries(
    Object.entries(state.rolls).filter(
      ([key, value]) => keys.has(key) && typeof value === "number" && Number.isFinite(value),
    ),
  ) as Record<string, number>;
}
