import type { WfrpActor } from "../../../types/foundry";
import type { MutationAcquisitionState } from "../../../types/mutants-handbook";
import { actorEligibilityBlocks, eligibilityBlock } from "./acquisition-eligibility";
import {
  activeMutationNamed,
  activeMutations,
  hasEligibleAdditionalLegs,
  normalizeName,
  selectionValues,
} from "./document-helpers";
import type { MutationAcquisitionBlock, ResolvedMutation } from "./document-types";

const LEG_SELECTIONS: Readonly<Record<string, readonly [string, readonly string[]]>> = {
  "additional appendages": ["location", ["foot"]],
  "atrophy": ["atrophied-part", ["foot", "leg", "toes"]],
  "elongated limbs": ["limb", ["legs"]],
  "extra joints": ["jointed-limbs", ["legs"]],
};
const BESTIAL_FUR_SOURCES: Readonly<Record<string, readonly string[]>> = {
  "bestial arms": ["bear", "canine", "caprine", "feline", "mustelid", "primate", "rodent"],
  "bestial body": ["bear", "canine", "caprine", "feline", "primate"],
  "bestial feature": ["bear", "canine", "caprine", "feline", "mustelid", "primate", "rodent"],
  "bestial head": ["bear", "canine", "caprine", "feline", "primate"],
  "bestial legs": ["bear", "canine", "caprine", "feline", "mustelid", "primate", "rodent"],
};

function uniqueBlocks(blocks: readonly MutationAcquisitionBlock[]): MutationAcquisitionBlock[] {
  return blocks.filter(
    (block, index) =>
      blocks.findIndex(
        (candidate) => candidate.kind === block.kind && candidate.message === block.message,
      ) === index,
  );
}

export function getMutationAcquisitionBlockDetails(
  actor: WfrpActor,
  mutation: ResolvedMutation,
  ignoreItemId?: string,
): MutationAcquisitionBlock[] {
  const active = activeMutations(actor, ignoreItemId);
  const existing = active.filter(
    (item) => normalizeName(item.name) === normalizeName(mutation.name),
  ).length;
  const maximum = mutation.acquisition?.max;
  const blocks: MutationAcquisitionBlock[] = [];

  if (maximum !== undefined && existing >= maximum) {
    blocks.push({
      kind: "maximum",
      message: `${mutation.name} has reached its acquisition maximum of ${maximum}.`,
    });
  }

  blocks.push(...actorEligibilityBlocks(actor, mutation, ignoreItemId));
  for (const conflict of mutation.acquisition?.conflicts ?? []) {
    if (!active.some((item) => normalizeName(item.name) === normalizeName(conflict))) continue;
    blocks.push({
      kind: "conflict",
      message: `${mutation.name} conflicts with the existing ${conflict} mutation.`,
    });
  }
  return uniqueBlocks(blocks);
}

export function getMutationAcquisitionBlockDetail(
  actor: WfrpActor,
  mutation: ResolvedMutation,
  ignoreItemId?: string,
): MutationAcquisitionBlock | undefined {
  return getMutationAcquisitionBlockDetails(actor, mutation, ignoreItemId)[0];
}

export function getResolvedMutationAcquisitionBlockDetails(
  actor: WfrpActor,
  mutationName: string,
  state: Pick<MutationAcquisitionState, "selections" | "status">,
  ignoreItemId?: string,
): MutationAcquisitionBlock[] {
  if (state.status !== "resolved") return [];
  const name = normalizeName(mutationName);
  const blocks: MutationAcquisitionBlock[] = [];
  if (
    name === "elongated limbs" &&
    selectionValues(state.selections["limb"]).includes("neck") &&
    activeMutationNamed(actor, "Headless", ignoreItemId)
  ) {
    blocks.push(eligibilityBlock(`${mutationName} (Neck) cannot be acquired with Headless.`));
  }

  const legSelection = LEG_SELECTIONS[name];
  if (
    legSelection &&
    selectionValues(state.selections[legSelection[0]]).some((value) =>
      legSelection[1].includes(value),
    ) &&
    activeMutationNamed(actor, "Blob", ignoreItemId) &&
    !hasEligibleAdditionalLegs(actor, ignoreItemId)
  ) {
    blocks.push(
      eligibilityBlock(
        `${mutationName} selected a leg-altering result, but ${actor.name} has Blob and no resolved Additional Extremities (Legs).`,
      ),
    );
  }
  if (name === "questing eye") {
    const eye = state.selections["questing-eye"];
    const subject =
      typeof eye === "string" && eye.trim().length > 0 ? `“${eye.trim()}” is` : "the chosen eye is";
    blocks.push(
      eligibilityBlock(
        `Confirm that ${subject} an existing eye available to receive ${mutationName}; exact eye anatomy is not reliably detectable.`,
      ),
    );
  }
  if (activeMutationNamed(actor, "Hairless", ignoreItemId)) {
    const bestialFur = BESTIAL_FUR_SOURCES[name];
    const producesFur =
      (name === "protective skin" && selectionValues(state.selections["skin"]).includes("fur")) ||
      (bestialFur !== undefined &&
        selectionValues(state.selections["bestial-source"]).some((source) =>
          bestialFur.includes(source),
        ));
    if (producesFur) {
      blocks.push(
        eligibilityBlock(
          `${mutationName} selected a hair or fur result, but Hairless prevents that manifestation; confirm whether to keep or reroll it.`,
        ),
      );
    }
  }
  return uniqueBlocks(blocks);
}

export function getMutationAcquisitionBlock(
  actor: WfrpActor,
  mutation: ResolvedMutation,
): string | undefined {
  return getMutationAcquisitionBlockDetail(actor, mutation)?.message;
}
